    {
        [ClinicPrintKind.Prescription] = "",
        [ClinicPrintKind.LabRequest] = "",
        [ClinicPrintKind.MedicalCertificate] = "",
        [ClinicPrintKind.QueueSlip] = "",
        [ClinicPrintKind.Receipt] = "",
    };

    public static ImageSource? For(ClinicPrintKind kind) =>
        Png.TryGetValue(kind, out var b) ? ImageSource.FromStream(() => new MemoryStream(Convert.FromBase64String(b))) : null;
